# Reset Crash Dumps to Default (Automatic/Kernel) Write-Host "Resetting crash dump settings to default..." -ForegroundColor Cyan Set-ItemProperty -Path "HKLM:\SYSTEM\CurrentControlSet\Control\CrashControl" -Name "CrashDumpEnabled" -Value 7 -Type DWord -Force -ErrorAction SilentlyContinue Set-ItemProperty -Path "HKLM:\SYSTEM\CurrentControlSet\Control\CrashControl" -Name "AutoReboot" -Value 1 -Type DWord -Force -ErrorAction SilentlyContinue Set-ItemProperty -Path "HKLM:\SYSTEM\CurrentControlSet\Control\CrashControl" -Name "Overwrite" -Value 1 -Type DWord -Force -ErrorAction SilentlyContinue Write-Host "Crash dumps reset to default (automatic)." -ForegroundColor Green